var firstMissingPositive = function(nums) {
    const n = nums.length;

    // Phase 1: Place numbers in their correct positions
    // A number 'x' should ideally be at index 'x-1'
    for (let i = 0; i < n; i++) {
        // Keep swapping while:
        // 1. nums[i] is positive and within the range [1, n]
        // 2. nums[i] is NOT already at its correct position (i.e., nums[i] != i + 1)
        // 3. The number at the target position nums[nums[i]-1] is not already nums[i]
        //    (prevents infinite loops for duplicates like [1,1])
        while (nums[i] > 0 && nums[i] <= n && nums[i] !== nums[nums[i] - 1]) {
            const correctPos = nums[i] - 1;
            [nums[i], nums[correctPos]] = [nums[correctPos], nums[i]];
        }
    }

    // Phase 2: Find the first missing positive
    for (let i = 0; i < n; i++) {
        if (nums[i] !== i + 1) {
            return i + 1;
        }
    }

    // If all numbers from 1 to n are present, then n + 1 is the answer
    return n + 1;
};

